; cost.asm -- chapter 12: every stack instruction and exchange
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "cost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
keep    EQU VARS               ; a word of RAM for SP
; Every instruction that works the stack or swaps registers, one after
; another, each with a label for the debugger to stop at.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
c1:     push bc                 ; PUSH
c2:     ex (sp), hl             ; HL and the top of the stack swapped ...
c3:     ex (sp), hl             ; ... and swapped back
c4:     pop bc                  ; POP
c5:     push ix
c6:     ex (sp), ix
c7:     pop ix
c8:     call sub                ; CALL
c9:     ex af, af'              ; AF and AF' swapped ...
c10:    ex af, af'              ; ... and back
c11:    exx                     ; BC, DE and HL and the second set swapped ...
c12:    exx                     ; ... and back
c13:    ex de, hl
c14:    ld (keep), sp           ; SP into memory
c15:    ld hl, $C800
c16:    ld sp, hl               ; SP from HL
c17:    inc sp
c18:    dec sp
c19:    add hl, sp
c20:    ld ix, $C800
c21:    ld sp, ix
c22:    ld sp, $C800
c23:    ld sp, (keep)           ; SP from memory
c24:    nop
stop:   jr stop

sub:    ret                     ; RET
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
